<script setup lang="ts">
import { computed } from 'vue'
import { ArrowRight, Plus, CalendarDays, Laptop, ArrowUpRight, Sun, Coffee, Leaf } from 'lucide-vue-next'
import { useApi } from '../composables/query'
import { useSession } from '../stores/session'
import type { Dashboard } from '../types'
import AsyncState from '../components/AsyncState.vue'
import BalanceCard from '../components/BalanceCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EmployeeAvatar from '../components/EmployeeAvatar.vue'
import DataTable from '../components/DataTable.vue'
import { dateRange, shortDate } from '../services/dates'
const session=useSession(), {data,loading,error,refresh}=useApi<Dashboard>('/me/dashboard')
const balance=computed(()=>data.value?.balances[0]), next=computed(()=>data.value?.upcoming.find(r=>r.kind==='LEAVE'))
const today=computed(()=>Object.values(data.value?.today.statistics||{})[0]||{office:0,remote:0,leave:0})
</script>
<template><div class="page-heading"><div><div class="eyebrow">YOUR DAY, A LITTLE CLEARER</div><h1>Hey {{session.user?.first_name}} <span class="greeting-sun">☀</span></h1><p>Here’s what’s happening in your corner of the world.</p></div><RouterLink to="/calendar" class="btn secondary"><CalendarDays :size="17"/>View team calendar</RouterLink></div><AsyncState :loading="loading" :error="error" @retry="refresh"><template v-if="data"><section class="welcome-banner"><div><span class="banner-label"><span/> FIND YOUR BALANCE</span><h2>Good work starts<br>with time for you.</h2><p>A change of scenery. A well-earned break.<br>Plan your days, your way.</p><div class="banner-actions"><RouterLink to="/request/vacation" class="btn light"><Plus :size="17"/>Request vacation</RouterLink><RouterLink to="/request/mobile" class="banner-link">Request mobile work <ArrowUpRight :size="17"/></RouterLink></div></div><div class="banner-art" aria-hidden="true"><div class="art-orbit orbit-one"/><div class="art-orbit orbit-two"/><div class="art-sun"/><div class="art-hill hill-back"/><div class="art-hill hill-front"/><div class="art-card"><Sun :size="22"/><span>A little room<br>to recharge.</span><div class="art-card-line"/></div><div class="art-leaf leaf-one"/><div class="art-leaf leaf-two"/><div class="art-stem"/></div></section><div class="stats-grid"><BalanceCard label="Vacation balance" :value="balance?.available??0" caption="Available for your next adventure" accent><div class="mini-progress"><i :style="{width:`${Math.min(100,Number(balance?.available||0)/Math.max(1,Number(balance?.granted||1))*100)}%`}"/></div></BalanceCard><BalanceCard label="Vacation booked" :value="balance?.used??0" :caption="`Of ${balance?.granted??0} days granted this year`"/><BalanceCard label="Awaiting approval" :value="balance?.pending??0" :caption="`${data.pending_count} pending request${data.pending_count===1?'':'s'}`"/><BalanceCard label="Mobile work this month" :value="data.mobile.used" :caption="`${data.mobile.remaining} of ${data.mobile.limit} days still available`"/></div><div class="dashboard-columns"><section class="panel"><div class="section-heading"><h2>Your requests <span class="subtle-count">{{data.recent.length}}</span></h2><RouterLink to="/requests" class="text-link">View all <ArrowRight :size="15"/></RouterLink></div><DataTable v-if="data.recent.length" :headers="['Request','Dates','Days','Status']"><tr v-for="request in data.recent.slice(0,5)" :key="request.id"><td><RouterLink :to="`/requests?selected=${request.id}`" class="request-cell"><span class="request-icon" :class="request.kind.toLowerCase()"><CalendarDays v-if="request.kind==='LEAVE'" :size="17"/><Laptop v-else :size="17"/></span><strong>{{request.label}}</strong></RouterLink></td><td>{{dateRange(request.start_date,request.end_date)}}</td><td>{{request.days}}</td><td><StatusBadge :status="request.status"/></td></tr></DataTable><div v-else class="empty-state"><Coffee :size="30"/><h3>Your next chapter starts here</h3><p>Request some time away or plan a mobile-work day.</p><RouterLink to="/request/vacation" class="text-link">Make your first request <ArrowRight :size="16"/></RouterLink></div></section><section class="panel upcoming-card"><div class="section-heading"><h2>On the horizon</h2><Sun :size="19" class="muted"/></div><template v-if="next"><div class="next-date"><span>{{new Date(next.start_date+'T12:00').toLocaleDateString('en-GB',{month:'short'})}}</span><strong>{{new Date(next.start_date+'T12:00').getDate()}}</strong></div><h3>Your next vacation</h3><p>{{dateRange(next.start_date,next.end_date)}} · {{next.days}} days to unwind</p><StatusBadge status="APPROVED"/></template><template v-else><div class="upcoming-illustration"><Leaf :size="32"/></div><h3>Something to look forward to</h3><p>Your next approved break will appear here. Where will you go?</p><RouterLink to="/request/vacation" class="text-link">Plan some time off <ArrowRight :size="16"/></RouterLink></template><div v-for="r in data.upcoming.filter(r=>r.kind==='MOBILE').slice(0,2)" :key="r.id" class="upcoming-remote"><Laptop :size="16"/><span>Mobile work · {{shortDate(r.start_date)}}</span></div></section></div><section class="panel team-today"><div class="section-heading"><div><h2>Your team today</h2><p class="muted">Different places. Same great team.</p></div><RouterLink to="/calendar" class="text-link">Open calendar <ArrowRight :size="15"/></RouterLink></div><div class="team-stats"><span><i class="dot office"/>{{today.office}} in the office</span><span><i class="dot mobile"/>{{today.remote}} working remotely</span><span><i class="dot leave"/>{{today.leave}} away</span></div><div class="team-people"><div v-for="person in data.today.employees.slice(0,8)" :key="person.id" class="team-person"><EmployeeAvatar :name="person.name"/><div><strong>{{person.name}}</strong><span>{{data.today.events.filter(e=>e.employee_id===person.id&&e.status!=='PENDING').map(e=>e.kind==='OFFICE'?'In the office':e.kind==='MOBILE'?'Working remotely':'On leave').join(' / ')||'Not scheduled'}}</span></div></div></div></section></template></AsyncState></template>
